function analyze_logs_js(args) {
    const logLines = args.log_lines || [];

    let errorCount = 0;
    let warningCount = 0;
    let infoCount = 0;
    const responseTimes = [];

    for (const line of logLines) {
        const lower = line.toLowerCase();

        if (lower.includes('error') || lower.includes('exception')) {
            errorCount++;
        } else if (lower.includes('warn')) {
            warningCount++;
        } else if (lower.includes('info')) {
            infoCount++;
        }

        const match = line.match(/response_time=(\d+)ms/);
        if (match) {
            responseTimes.push(parseInt(match[1], 10));
        }
    }

    const avgResponseTime = responseTimes.length > 0
        ? responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length
        : 0;

    const maxResponseTime = responseTimes.length > 0
        ? Math.max(...responseTimes)
        : 0;

    return {
        total_lines: logLines.length,
        error_count: errorCount,
        warning_count: warningCount,
        info_count: infoCount,
        avg_response_time_ms: Math.round(avgResponseTime * 100) / 100,
        slowest_request_ms: maxResponseTime
    };
}
